{"content": "import tilelang
import tilelang.language as T

pass_configs = {
    tilelang.PassConfigKey.TL_ASCEND_AUTO_SYNC: True,
}


@tilelang.jit(out_idx=[0], pass_configs=pass_configs)
def pad_1d(N, pad_left, pad_right, mode="constant", value=0.0, dtype="float32"):
    """Tile-level design for 1D padding.

    Output shape: (N + pad_left + pad_right,).
    Each block handles a contiguous segment of the output.
    """
    block_size = 128
    out_N = N + pad_left + pad_right
    block_num = (out_N + block_size - 1) // block_size
    num_physical_cores = 20
    usedCoreNum = min(num_physical_cores, block_num)
    tasksPerCore = (block_num + usedCoreNum - 1) // usedCoreNum

    @T.prim_func
    def main(
        Input: T.Tensor((N,), dtype),
        Output: T.Tensor((out_N,), dtype),
    ):
        with T.Kernel(usedCoreNum, is_npu=True) as (cid, vid):
            coreIdx = cid
            for localIdx in T.serial(tasksPerCore):
                bx = coreIdx * tasksPerCore + localIdx
                with T.Scope("V"):
                    if bx < block_num:
                        out_start = bx * block_size
                        out_end = T.min(out_start + block_size, out_N)
                        tile_len = out_end - out_start

                        # Allocate UB buffer for output tile
                        out_ub = T.alloc_ub((block_size,), dtype)

                        # Fill with constant value first (for padding regions)
                        if mode == "constant":
                            val = T.cast(T.float32(value), dtype)
                            T.tile.fill(out_ub, val)

                        # For each position in output tile, compute source index
                        # and copy from input if valid
                        # We use scalar loop for index computation since
                        # padding modes require conditional logic per element
                        for i in T.serial(tile_len):
                            out_idx = out_start + i
                            src_idx = 0
                            valid = False

                            if mode == "constant":
                                if out_idx >= pad_left and out_idx < pad_left + N:
                                    src_idx = out_idx - pad_left
                                    valid = True
                            elif mode == "reflect":
                                if out_idx < pad_left:
                                    src_idx = pad_left - out_idx
                                    valid = True
                                elif out_idx >= pad_left + N:
                                    src_idx = 2 * (N - 1) + pad_left - out_idx
                                    valid = True
                                else:
                                    src_idx = out_idx - pad_left
                                    valid = True
                            elif mode == "replicate":
                                if out_idx < pad_left:
                                    src_idx = 0
                                    valid = True
                                elif out_idx >= pad_left + N:
                                    src_idx = N - 1
                                    valid = True
                                else:
                                    src_idx = out_idx - pad_left
                                    valid = True
                            elif mode == "circular":
                                if out_idx < pad_left:
                                    src_idx = N + out_idx - pad_left
                                    valid = True
                                elif out_idx >= pad_left + N:
                                    src_idx = out_idx - pad_left - N
                                    valid = True
                                else:
                                    src_idx = out_idx - pad_left
                                    valid = True

                            if valid:
                                out_ub[i] = Input[src_idx]

                        # Write UB tile back to Output GM
                        T.copy(out_ub[0:tile_len], Output[out_start:out_end])

    return main


@tilelang.jit(out_idx=[0], pass_configs=pass_configs)
def pad_2d(H, W, pad_left, pad_right, pad_top, pad_bottom,
         mode="constant", value=0.0, dtype="float32"):
    """Tile-level design for 2D padding.

    Output shape: (H + pad_top + pad_bottom, W + pad_left + pad_right).
    Each block handles a set of contiguous output rows.
    """
    block_H = 16
    out_H = H + pad_top + pad_bottom
    out_W = W + pad_left + pad_right
    h_block_num = (out_H + block_H - 1) // block_H
    num_physical_cores = 20
    usedCoreNum = min(num_physical_cores, h_block_num)
    tasksPerCore = (h_block_num + usedCoreNum - 1) // usedCoreNum

    @T.prim_func
    def main(
        Input: T.Tensor((H, W), dtype),
        Output: T.Tensor((out_H, out_W), dtype),
    ):
        with T.Kernel(usedCoreNum, is_npu=True) as (cid, vid):
            coreIdx = cid
            for localIdx in T.serial(tasksPerCore):
                bx = coreIdx * tasksPerCore + localIdx
                with T.Scope("V"):
                    if bx < h_block_num:
                        row_start = bx * block_H
                        row_end = T.min(row_start + block_H, out_H)
                        tile_rows = row_end - row_start

                        # Allocate UB for output tile
                        out_ub = T.alloc_ub((block_H, out_W), dtype)

                        # Fill with constant value
                        if mode == "constant":
                            val = T.cast(T.float32(value), dtype)
                            T.tile.fill(out_ub, val)

                        # For each output row in tile
                        for r in T.serial(tile_rows):
                            out_row = row_start + r
                            src_row = 0
                            row_valid = False

                            # Compute source row index
                            if mode == "constant":
                                if out_row >= pad_top and out_row < pad_top + H:
                                    src_row = out_row - pad_top
                                    row_valid = True
                            elif mode == "reflect":
                                if out_row < pad_top:
                                    src_row = pad_top - out_row
                                    row_valid = True
                                elif out_row >= pad_top + H:
                                    src_row = 2 * (H - 1) + pad_top - out_row
                                    row_valid = True
                                else:
                                    src_row = out_row - pad_top
                                    row_valid = True
                            elif mode == "replicate":
                                if out_row < pad_top:
                                    src_row = 0
                                    row_valid = True
                                elif out_row >= pad_top + H:
                                    src_row = H - 1
                                    row_valid = True
                                else:
                                    src_row = out_row - pad_top
                                    row_valid = True
                            elif mode == "circular":
                                if out_row < pad_top:
                                    src_row = H + out_row - pad_top
                                    row_valid = True
                                elif out_row >= pad_top + H:
                                    src_row = out_row - pad_top - H
                                    row_valid = True
                                else:
                                    src_row = out_row - pad_top
                                    row_valid = True

                            if row_valid:
                                # For each column in the row
                                for c in T.serial(out_W):
                                    src_col = 0
                                    col_valid = False

                                    if mode == "constant":
                                        if c >= pad_left and c < pad_left + W:
                                            src_col = c - pad_left
                                            col_valid = True
                                    elif mode == "reflect":
                                        if c < pad_left:
                                            src_col = pad_left - c
                                            col_valid = True
                                        elif c >= pad_left + W:
                                            src_col = 2 * (W - 1) + pad_left - c
                                            col_valid = True
                                        else:
                                            src_col = c - pad_left
                                            col_valid = True
                                    elif mode == "replicate":
                                        if c < pad_left:
                                            src_col = 0
                                            col_valid = True
                                        elif c >= pad_left + W:
                                            src_col = W - 1
                                            col_valid = True
                                        else:
                                            src_col = c - pad_left
                                            col_valid = True
                                    elif mode == "circular":
                                        if c < pad_left:
                                            src_col = W + c - pad_left
                                            col_valid = True
                                        elif c >= pad_left + W:
                                            src_col = c - pad_left - W
                                            col_valid = True
                                        else:
                                            src_col = c - pad_left
                                            col_valid = True

                                    if col_valid:
                                        out_ub[r, c] = Input[src_row, src_col]

                        # Write back to GM
                        T.copy(out_ub[0:tile_rows, 0:out_W], Output[row_start:row_end, 0:out_W])

    return main


@tilelang.jit(out_idx=[0], pass_configs=pass_configs)
def pad_nd(shape, pad, mode="constant", value=0.0, dtype="float32"):
    """Tile-level design for N-D padding.

    For N-D tensor, pad applies to the last len(pad)//2 dimensions.
    We flatten all non-padded dimensions and split along the flattened dimension.
    """
    ndim = len(shape)
    pad_dims = len(pad) // 2
    out_shape = list(shape)
    for i in range(pad_dims):
        out_shape[ndim - pad_dims + i] = shape[ndim - pad_dims + i] + pad[2 * i] + pad[2 * i + 1]

    outer_size = 1
    for i in range(ndim - pad_dims):
        outer_size *= shape[i]

    inner_size = 1
    for i in range(pad_dims):
        inner_size *= out_shape[ndim - pad_dims + i]

    block_size = 128
    total_out = outer_size * inner_size
    block_num = (total_out + block_size - 1) // block_size
    num_physical_cores = 20
    usedCoreNum = min(num_physical_cores, block_num)
    tasksPerCore = (block_num + usedCoreNum - 1) // usedCoreNum

    @T.prim_func
    def main(
        Input: T.Tensor(shape, dtype),
        Output: T.Tensor(out_shape, dtype),
    ):
        with T.Kernel(usedCoreNum, is_npu=True) as (cid, vid):
            coreIdx = cid
            for localIdx in T.serial(tasksPerCore):
                bx = coreIdx * tasksPerCore + localIdx
                with T.Scope("V"):
                    if bx < block_num:
                        out_start = bx * block_size
                        out_end = T.min(out_start + block_size, total_out)
                        tile_len = out_end - out_start

                        # Allocate UB buffer
                        out_ub = T.alloc_ub((block_size,), dtype)

                        # Fill with constant value
                        if mode == "constant":
                            val = T.cast(T.float32(value), dtype)
                            T.tile.fill(out_ub, val)

                        # For each flat output index, compute multi-dim index
                        # then determine source and copy
                        for i in T.serial(tile_len):
                            flat_idx = out_start + i

                            # Convert flat to multi-dimensional output index
                            out_idx = [0] * ndim
                            tmp = flat_idx
                            for d in range(ndim - 1, -1, -1):
                                out_idx[d] = tmp % out_shape[d]
                                tmp = tmp // out_shape[d]

                            # Check if in valid (non-padded) region
                            valid = True
                            src_idx = [0] * ndim
                            for d in range(pad_dims):
                                dim_idx = ndim - pad_dims + d
                                p_left = pad[2 * d]
                                p_right = pad[2 * d + 1]
                                out_pos = out_idx[dim_idx]

                                if mode == "constant":
                                    if out_pos < p_left or out_pos >= p_left + shape[dim_idx]:
                                        valid = False
                                    else:
                                        src_idx[dim_idx] = out_pos - p_left
                                elif mode == "reflect":
                                    if out_pos < p_left:
                                        src_idx[dim_idx] = p_left - out_pos
                                    elif out_pos >= p_left + shape[dim_idx]:
                                        src_idx[dim_idx] = 2 * (shape[dim_idx] - 1) + p_left - out_pos
                                    else:
                                        src_idx[dim_idx] = out_pos - p_left
                                elif mode == "replicate":
                                    if out_pos < p_left:
                                        src_idx[dim_idx] = 0
                                    elif out_pos >= p_left + shape[dim_idx]:
                                        src_idx[dim_idx] = shape[dim_idx] - 1
                                    else:
                                        src_idx[dim_idx] = out_pos - p_left
                                elif mode == "circular":
                                    if out_pos < p_left:
                                        src_idx[dim_idx] = shape[dim_idx] + out_pos - p_left
                                    elif out_pos >= p_left + shape[dim_idx]:
                                        src_idx[dim_idx] = out_pos - p_left - shape[dim_idx]
                                    else:
                                        src_idx[dim_idx] = out_pos - p_left

                            # For non-padded dimensions, src_idx = out_idx
                            for d in range(ndim - pad_dims):
                                src_idx[d] = out_idx[d]

                            if valid:
                                # Convert multi-dim src_idx to flat input index
                                flat_src = 0
                                stride = 1
                                for d in range(ndim - 1, -1, -1):
                                    flat_src += src_idx[d] * stride
                                    stride *= shape[d]
                                out_ub[i] = Input[flat_src]

                        # Write back to GM
                        T.copy(out_ub[0:tile_len], Output[out_start:out_end])

    return main
