20	#include "kernel_operator.h"
21	
22	constexpr int32_t BUFFER_NUM = 2;
23	
24	template <typename T>
25	class Kernel<OpName> {
26	public:
27	    __aicore__ inline Kernel<OpName>() {}
28	
29	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
30	                                int64_t formerNum, int64_t formerLength,
31	                                int64_t tailLength, int64_t tileLength)
32	    {
33	        int64_t blockIdx = AscendC::GetBlockIdx();
34	
35	        if (blockIdx < formerNum) {
36	            this->blockLength = formerLength;
37	            int64_t offset = formerLength * blockIdx;
38	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
39	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
40	        } else {
41	            this->blockLength = tailLength;
42	            int64_t tailIdx = blockIdx - formerNum;
43	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
44	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
45	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
46	        }
47	
48	        this->tileLength = tileLength;
49	
50	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
51	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
52	        // 如需升精度计算 (FP16/BF16), 添加 FP32 临时缓冲:pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
53	    }
54	
55	    __aicore__ inline void Process()
56	    {
57	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
58	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
59	
60	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
61	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
62	
63	        for (int64_t i = 0; i < tileNum - 1; ++i) {
