120	extern "C" __global__ __aicore__ void <op_name>(GM_ADDR x, GM_ADDR y,
121	                                                 int64_t formerNum, int64_t formerLength,
122	                                                 int64_t tailLength, int64_t tileLength,
123	                                                 int64_t dtypeSize)
124	{
