 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Pad modes
constexpr int32_t PAD_MODE_CONSTANT = 0;
constexpr int32_t PAD_MODE_REFLECT = 1;
constexpr int32_t PAD_MODE_REPLICATE = 2;
constexpr int32_t PAD_MODE_CIRCULAR = 3;

template <typename T>
class KernelPad {
public:
    __aicore__ inline KernelPad() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output,
                                int64_t totalOutElements,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t inputDims,
                                int64_t padLeft0, int64_t padRight0,
                                int64_t padLeft1, int64_t padRight1,
                                int64_t padLeft2, int64_t padRight2,
                                int64_t padLeft3, int64_t padRight3,
                                int64_t inShape0, int64_t inShape1,
                                int64_t inShape2, int64_t inShape3,
                                int64_t outShape0, int64_t outShape1,
                                int64_t outShape2, int64_t outShape3,
                                int64_t padMode, float padValue)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            this->blockOffset = offset;
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            this->blockOffset = offset;
        }

        this->tileLength = tileLength;
        this->totalOutElements = totalOutElements;
        this->inputDims = inputDims;

        this->padLeft[0] = padLeft0;
        this->padRight[0] = padRight0;
        this->padLeft[1] = padLeft1;
        this->padRight[1] = padRight1;
        this->padLeft[2] = padLeft2;
        this->padRight[2] = padRight2;
        this->padLeft[3] = padLeft3;
        this->padRight[3] = padRight3;

        this->inShape[0] = inShape0;
        this->inShape[1] = inShape1;
        this->inShape[2] = inShape2;
        this->inShape[3] = inShape3;

        this->outShape[0] = outShape0;
        this->outShape[1] = outShape1;
        this->outShape[2] = outShape2;
        this->outShape[3] = outShape3;

        this->padMode = padMode;
        this->padValue = padValue;

        outGm.SetGlobalBuffer((__gm__ T *)output, totalOutElements);
        inGm.SetGlobalBuffer((__gm__ T *)input, totalOutElements);

        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        int64_t outStart = this->blockOffset + progress * this->tileLength;

        // Fill with pad value first (for constant mode)
        if (this->padMode == PAD_MODE_CONSTANT) {
            T val = static_cast<T>(this->padValue);
            AscendC::Duplicate(yLocal, val, curTileLength);
        }

        // For each output element in this tile, compute source index and copy
        for (int64_t i = 0; i < curTileLength; ++i) {
            int64_t flatOutIdx = outStart + i;
            if (flatOutIdx >= this->totalOutElements) {
                continue;
            }

            // Convert flat output index to multi-dimensional output index
            int64_t outIdx[4] = {0, 0, 0, 0};
            int64_t tmp = flatOutIdx;
            for (int d = this->inputDims - 1; d >= 0; --d) {
                outIdx[d] = tmp % this->outShape[d];
                tmp = tmp / this->outShape[d];
            }

            // Check if in valid (non-padded) region and compute source index
            bool valid = true;
            int64_t srcIdx[4] = {0, 0, 0, 0};

            for (int d = 0; d < this->inputDims; ++d) {
                int64_t pLeft = this->padLeft[d];
                int64_t pRight = this->padRight[d];
                int64_t outPos = outIdx[d];
                int64_t inSize = this->inShape[d];

                if (this->padMode == PAD_MODE_CONSTANT) {
                    if (outPos < pLeft || outPos >= pLeft + inSize) {
                        valid = false;
                        break;
                    }
                    srcIdx[d] = outPos - pLeft;
                } else if (this->padMode == PAD_MODE_REFLECT) {
                    if (outPos < pLeft) {
                        srcIdx[d] = pLeft - outPos;
                    } else if (outPos >= pLeft + inSize) {
                        srcIdx[d] = 2 * (inSize - 1) + pLeft - outPos;
                    } else {
                        srcIdx[d] = outPos - pLeft;
                    }
                    // Clamp to valid range
                    if (srcIdx[d] < 0) srcIdx[d] = 0;
                    if (srcIdx[d] >= inSize) srcIdx[d] = inSize - 1;
                } else if (this->padMode == PAD_MODE_REPLICATE) {
                    if (outPos < pLeft) {
                        srcIdx[d] = 0;
                    } else if (outPos >= pLeft + inSize) {
                        srcIdx[d] = inSize - 1;
                    } else {
                        srcIdx[d] = outPos - pLeft;
                    }
                } else if (this->padMode == PAD_MODE_CIRCULAR) {
                    if (outPos < pLeft) {
                        srcIdx[d] = inSize + outPos - pLeft;
                    } else if (outPos >= pLeft + inSize) {
                        srcIdx[d] = outPos - pLeft - inSize;
                    } else {
                        srcIdx[d] = outPos - pLeft;
                    }
                    // Wrap around
                    srcIdx[d] = ((srcIdx[d] % inSize) + inSize) % inSize;
                }
            }

            if (valid) {
                // Convert multi-dimensional src index to flat input index
                int64_t flatSrcIdx = 0;
                int64_t stride = 1;
                for (int d = this->inputDims - 1; d >= 0; --d) {
                    flatSrcIdx += srcIdx[d] * stride;
                    stride *= this->inShape[d];
                }
                yLocal[i] = inGm[flatSrcIdx];
            }
        }

        outQueueY.EnQue<T>(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        int64_t outOffset = this->blockOffset + progress * this->tileLength;
        AscendC::DataCopyPad(outGm[outOffset], yLocal, curTileLength);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::GlobalTensor<T> outGm;
    AscendC::GlobalTensor<T> inGm;

    int64_t blockLength;
    int64_t blockOffset;
    int64_t tileLength;
    int64_t totalOutElements;
    int64_t inputDims;
    int64_t padLeft[4];
    int64_t padRight[4];
    int64_t inShape[4];
    int64_t outShape[4];
    int64_t padMode;
    float padValue;
};

extern "C" __global__ __aicore__ void pad(GM_ADDR input, GM_ADDR output,
                                           int64_t totalOutElements,
                                           int64_t formerNum, int64_t formerLength,
                                           int64_t tailLength, int64_t tileLength,
                                           int64_t inputDims,
                                           int64_t padLeft0, int64_t padRight0,
                                           int64_t padLeft1, int64_t padRight1,
                                           int64_t padLeft2, int64_t padRight2,
                                           int64_t padLeft3, int64_t padRight3,
                                           int64_t inShape0, int64_t inShape1,
                                           int64_t inShape2, int64_t inShape3,
                                           int64_t outShape0, int64_t outShape1,
                                           int64_t outShape2, int64_t outShape3,
                                           int64_t padMode, float padValue)
{
    KernelPad<half> op;
    op.Init(input, output, totalOutElements, formerNum, formerLength, tailLength, tileLength,
            inputDims, padLeft0, padRight0, padLeft1, padRight1, padLeft2, padRight2, padLeft3, padRight3,
            inShape0, inShape1, inShape2, inShape3, outShape0, outShape1, outShape2, outShape3,
            padMode, padValue);
    op.Process();
}
