#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_pad.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

// Pad mode mapping
constexpr int32_t PAD_MODE_CONSTANT = 0;
constexpr int32_t PAD_MODE_REFLECT = 1;
constexpr int32_t PAD_MODE_REPLICATE = 2;
constexpr int32_t PAD_MODE_CIRCULAR = 3;

at::Tensor pad(const at::Tensor &self, at::IntArrayRef pad, const std::string &mode, double value)
{
    // ---- Input validation ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "pad: only float16, float32 and bfloat16 are supported, got ", self.scalar_type());
    TORCH_CHECK(pad.size() % 2 == 0, "pad: pad tuple length must be even");
    TORCH_CHECK(pad.size() <= 8, "pad: at most 4 dimensions of padding supported");

    int64_t inputDims = self.dim();
    int64_t padDims = static_cast<int64_t>(pad.size() / 2);

    // Compute output shape
    std::vector<int64_t> outShape = self.sizes().vec();
    for (int64_t i = 0; i < padDims; ++i) {
        int64_t dimIdx = inputDims - padDims + i;
        if (dimIdx >= 0 && dimIdx < inputDims) {
            outShape[dimIdx] = outShape[dimIdx] + pad[2 * i] + pad[2 * i + 1];
        }
    }

    at::Tensor output = at::empty(outShape, self.options());

    int64_t totalOutElements = output.numel();
    if (totalOutElements == 0) {
        return output;
    }

    int64_t dtypeSize = self.element_size();

    // Pad parameters (up to 4 dimensions)
    int64_t padLeft[4] = {0, 0, 0, 0};
    int64_t padRight[4] = {0, 0, 0, 0};
    for (int64_t i = 0; i < padDims; ++i) {
        padLeft[i] = pad[2 * i];
        padRight[i] = pad[2 * i + 1];
    }

    // Input shape (up to 4 dimensions)
    int64_t inShape[4] = {1, 1, 1, 1};
    for (int64_t i = 0; i < inputDims; ++i) {
        inShape[i] = self.size(i);
    }

    // Output shape (up to 4 dimensions)
    int64_t outShapeArr[4] = {1, 1, 1, 1};
    for (int64_t i = 0; i < inputDims; ++i) {
        outShapeArr[i] = outShape[i];
    }

    // Pad mode
    int64_t padMode = PAD_MODE_CONSTANT;
    if (mode == "reflect") {
        padMode = PAD_MODE_REFLECT;
    } else if (mode == "replicate") {
        padMode = PAD_MODE_REPLICATE;
    } else if (mode == "circular") {
        padMode = PAD_MODE_CIRCULAR;
    }

    float padValue = static_cast<float>(value);

    // ---- Get hardware parameters ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block-level tiling (inter-core split, Cache Line aligned) ----
    int64_t totalLengthCore = (totalOutElements + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalOutElements + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalOutElements - formerNum * formerLength;

    // ---- UB-level tiling (intra-core split) ----
    // Single output queue with double buffer
    int64_t bufferCoefficient = dtypeSize * 2; // 1 queue * 2(double buf) * dtypeSize
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) { alignElements = 1; }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) { tileLength = alignElements; }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All parameters must be left values for EXEC_KERNEL_CMD
    int64_t totalOutElementsL = totalOutElements;
    int64_t formerNumL = formerNum;
    int64_t formerLengthL = formerLength;
    int64_t tailLengthL = tailLength;
    int64_t tileLengthL = tileLength;
    int64_t inputDimsL = inputDims;
    int64_t padLeft0 = padLeft[0];
    int64_t padRight0 = padRight[0];
    int64_t padLeft1 = padLeft[1];
    int64_t padRight1 = padRight[1];
    int64_t padLeft2 = padLeft[2];
    int64_t padRight2 = padRight[2];
    int64_t padLeft3 = padLeft[3];
    int64_t padRight3 = padRight[3];
    int64_t inShape0 = inShape[0];
    int64_t inShape1 = inShape[1];
    int64_t inShape2 = inShape[2];
    int64_t inShape3 = inShape[3];
    int64_t outShape0 = outShapeArr[0];
    int64_t outShape1 = outShapeArr[1];
    int64_t outShape2 = outShapeArr[2];
    int64_t outShape3 = outShapeArr[3];
    int64_t padModeL = padMode;
    float padValueL = padValue;
    int64_t dtypeSizeL = dtypeSize;

    EXEC_KERNEL_CMD(pad, blockDim,
                    self, output,
                    totalOutElementsL, formerNumL, formerLengthL, tailLengthL, tileLengthL,
                    inputDimsL,
                    padLeft0, padRight0, padLeft1, padRight1, padLeft2, padRight2, padLeft3, padRight3,
                    inShape0, inShape1, inShape2, inShape3,
                    outShape0, outShape1, outShape2, outShape3,
                    padModeL, padValueL, dtypeSizeL);

    return output;
}

}  // namespace ascend_kernel
