from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "pad_ext*")

# 优先 whl import（触发 TORCH_LIBRARY 注册）
try:
    import pad_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """
    AscendC implementation of Pad operator.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor, pad: tuple, mode: str = 'constant', value: float = None) -> torch.Tensor:
        """
        Pads tensor with specified padding mode using AscendC kernel.
        """
        val = value if value is not None else 0.0
        return torch.ops.npu.pad(x, pad, mode, val)
