10	
11	#include "torch_kernel_helper.h"
12	#include "tiling/platform/platform_ascendc.h"
13	#include "aclrtlaunch_pad.h"
14	
15	namespace ascend_kernel {
16	
17	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
18	
19	// Pad mode mapping
20	constexpr int32_t PAD_MODE_CONSTANT = 0;
21	constexpr int32_t PAD_MODE_REFLECT = 1;
22	constexpr int32_t PAD_MODE_REPLICATE = 2;
23	constexpr int32_t PAD_MODE_CIRCULAR = 3;
24	
25	at::Tensor pad(const at::Tensor &self, at::IntArrayRef pad, const std::string &mode, double value)
26	{
27	    // ---- Input validation ----
28	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
29	                "pad: only float16, float32 and bfloat16 are supported, got ", self.scalar_type());
30	    TORCH_CHECK(pad.size() % 2 == 0, "pad: pad tuple length must be even");
31	    TORCH_CHECK(pad.size() <= 8, "pad: at most 4 dimensions of padding supported");
32	
33	    int64_t inputDims = self.dim();
34	    int64_t padDims = static_cast<int64_t>(pad.size() / 2);
35	
36	    // Compute output shape
37	    // PyTorch pad applies from last dimension backward:
38	    //   pad[0,1] -> last dim (inputDims-1)
39	    //   pad[2,3] -> second last dim (inputDims-2), etc.
40	    std::vector<int64_t> outShape = self.sizes().vec();
41	    for (int64_t i = 0; i < padDims; ++i) {
42	        int64_t dimIdx = inputDims - 1 - i;
43	        if (dimIdx >= 0 && dimIdx < inputDims) {
44	            outShape[dimIdx] = outShape[dimIdx] + pad[2 * i] + pad[2 * i + 1];
45	        }
46	    }
47	
48	    at::Tensor output = at::empty(outShape, self.options());
49	
50	    int64_t totalOutElements = output.numel();
51	    if (totalOutElements == 0) {
52	        return output;
53	    }
54	
55	    int64_t dtypeSize = self.element_size();
56	
57	    // Pad parameters (up to 4 dimensions)
58	    // PyTorch pad tuple is ordered from last dimension to first:
59	    //   (left, right) for last dim
60	    //   (left, right, top, bottom) for last 2 dims
61	    //   etc.
62	    // Kernel dimensions are ordered from first to last (dim 0, 1, 2, 3)
63	    // For 2D input [H, W] with pad=(left, right, top, bottom):
64	    //   - W is the last dim (dim 1), gets pad (left, right) = pad[0:2]
65	    //   - H is the second last dim (dim 0), gets pad (top, bottom) = pad[2:4]
66	    // So we map: pad pair i (from last dim) -> kernel dim (inputDims - 1 - i)
67	    int64_t padLeft[4] = {0, 0, 0, 0};
68	    int64_t padRight[4] = {0, 0, 0, 0};
69	    for (int64_t i = 0; i < padDims; ++i) {
70	        // PyTorch pad pair i corresponds to input dimension (inputDims - 1 - i)
71	        int64_t kernelDim = inputDims - 1 - i;
72	        if (kernelDim >= 0 && kernelDim < 4) {
73	            padLeft[kernelDim] = pad[2 * i];
74	            padRight[kernelDim] = pad[2 * i + 1];
75	        }
76	    }
77	
78	    // Input shape (up to 4 dimensions)
79	    int64_t inShape[4] = {1, 1, 1, 1};
80	    for (int64_t i = 0; i < inputDims; ++i) {
81	        inShape[i] = self.size(i);
82	    }
83	
84	    // Output shape (up to 4 dimensions)
85	    int64_t outShapeArr[4] = {1, 1, 1, 1};
86	    for (int64_t i = 0; i < inputDims; ++i) {
87	        outShapeArr[i] = outShape[i];
88	    }
89	
90	    // Pad mode
91	    int64_t padMode = PAD_MODE_CONSTANT;
92	    if (mode == "reflect") {
93	        padMode = PAD_MODE_REFLECT;
94	    } else if (mode == "replicate") {
95	        padMode = PAD_MODE_REPLICATE;
96	    } else if (mode == "circular") {
97	        padMode = PAD_MODE_CIRCULAR;
98	    }
99	
100	    float padValue = static_cast<float>(value);
101	
102	    // Dtype identifier: 0=fp32, 1=fp16, 2=bf16
103	    int64_t dtypeId = 0;
104	    if (self.scalar_type() == at::kHalf) {
105	        dtypeId = 1;
106	    } else if (self.scalar_type() == at::kBFloat16) {
107	        dtypeId = 2;
108	    }
109	
110	    // ---- Get hardware parameters ----
111	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
112	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
113	    uint64_t ubSize;
114	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
115	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
116	
117	    // ---- Block-level tiling (inter-core split, Cache Line aligned) ----
118	    int64_t totalLengthCore = (totalOutElements + coreNum - 1) / coreNum;
119	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
120	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
121	
122	    int64_t usedCoreNum = (totalOutElements + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
123	    int64_t formerNum = usedCoreNum - 1;
124	    int64_t formerLength = totalLengthCoreAlign;
125	    int64_t tailLength = totalOutElements - formerNum * formerLength;
126	
127	    // ---- UB-level tiling (intra-core split) ----
128	    // Single output queue with double buffer
129	    int64_t bufferCoefficient = dtypeSize * 2; // 1 queue * 2(double buf) * dtypeSize
130	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
131	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
132	    int64_t alignElements = 32 / dtypeSize;
133	    if (alignElements == 0) { alignElements = 1; }
134	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
135	    if (tileLength == 0) { tileLength = alignElements; }
136	
137	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
138	
139	    // All parameters must be left values for EXEC_KERNEL_CMD
140	    int64_t totalOutElementsL = totalOutElements;
141	    int64_t formerNumL = formerNum;
142	    int64_t formerLengthL = formerLength;
143	    int64_t tailLengthL = tailLength;
144	    int64_t tileLengthL = tileLength;
145	    int64_t inputDimsL = inputDims;
146	    int64_t padLeft0 = padLeft[0];
147	    int64_t padRight0 = padRight[0];
148	    int64_t padLeft1 = padLeft[1];
149	    int64_t padRight1 = padRight[1];
150	    int64_t padLeft2 = padLeft[2];
151	    int64_t padRight2 = padRight[2];
152	    int64_t padLeft3 = padLeft[3];
153	    int64_t padRight3 = padRight[3];
154	    int64_t inShape0 = inShape[0];
155	    int64_t inShape1 = inShape[1];
156	    int64_t inShape2 = inShape[2];
157	    int64_t inShape3 = inShape[3];
158	    int64_t outShape0 = outShapeArr[0];
159	    int64_t outShape1 = outShapeArr[1];
160	    int64_t outShape2 = outShapeArr[2];
161	    int64_t outShape3 = outShapeArr[3];
162	    int64_t padModeL = padMode;
163	    float padValueL = padValue;
164	    int64_t dtypeSizeL = dtypeSize;
165	    int64_t dtypeIdL = dtypeId;
166	
167	    EXEC_KERNEL_CMD(pad, blockDim,
168	                    self, output,
169	                    totalOutElementsL, formerNumL, formerLengthL, tailLengthL, tileLengthL,
170	                    inputDimsL,
171	                    padLeft0, padRight0, padLeft1, padRight1, padLeft2, padRight2, padLeft3, padRight3,
172	                    inShape0, inShape1, inShape2, inShape3,
173	                    outShape0, outShape1, outShape2, outShape3,
174	                    padModeL, padValueL, dtypeSizeL, dtypeIdL);
175	
176	    return output;
177	}
178	
179	}  // namespace ascend_kernel
